mapper.select:
SELECT
FROM odin_formation_run_frames
ORDER BY frame_no ASC, id ASC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE odin_formation_run_frames
SET frame_status = 'Failed',
    finish_time = NOW(),
    attempt_count = attempt_count + 1,
    error_cause = #{errorCause}
WHERE guid = #{guid}
